SubmitButton.OnSelect:
If(!varSubmitting && varDisposition <> "exported" && varDisposition <> "conflict",
    Set(varSubmitting, true);
    Set(varSubmissionStatus, "Saving your highlight…");
    Set(varCanSend, false); Set(varCorrectionConflict, false);
    If(IsBlank(varPendingJson),
        IfError(
            With({newId: Lower(Text(GUID())), newAt: Text(Now(), DateTimeFormat.UTC)},
                With({base: {entry: {archived: false, category: CategoryDropdown.Selected.Value, eventType: If(EventTypeDropdown.Selected.Value = "Not specified", Blank(), EventTypeDropdown.Selected.Value), global: PlacementDropdown.Selected.Value = "Report-wide update (no associated project)", items: If(IsEmpty(Filter(Split(Substitute(ItemsInput.Text, Char(13), ""), Char(10)), !IsBlank(Trim(Value)))), Blank(), ForAll(Filter(Split(Substitute(ItemsInput.Text, Char(13), ""), Char(10)), !IsBlank(Trim(Value))), Trim(Value))), origin: "manual", state: StateDropdown.Selected.Value, summary: Trim(SummaryInput.Text), timestamp: Text(OccurredOnPicker.SelectedDate, DateTimeFormat.UTC)}, projectId: If(!IsBlank(varCorrectionParent), varEditingProjectId, PlacementDropdown.Selected.Value = "Report-wide update (no associated project)", "general", ProjectDropdown.Selected.ProjectId), submissionId: newId, submittedAt: newAt, submitter: {email: Lower(User().Email)}}}, With({payload: If(IsBlank(varCorrectionParent), JSON(base, JSONFormat.Compact & JSONFormat.FlattenValueTables), JSON(Patch(base, {revision: {rootSubmissionId: varCorrectionRoot, supersedesSubmissionId: varCorrectionParent}}), JSONFormat.Compact & JSONFormat.FlattenValueTables))},
                    Set(varPendingJson, payload); Set(varPendingId, newId); Set(varPendingProjectLabel, If(PlacementDropdown.Selected.Value = "Report-wide update (no associated project)", "Report-wide update", ProjectDropdown.Selected.Value)); Set(varDisposition, "pending"); Set(varCanSend, true)))),
            Set(varSubmissionStatus, "We couldn't prepare your highlight. Your entries are still here. Please try again.")),
        Set(varCanSend, true)
    );
    If(varCanSend,
        ClearCollect(colPendingHighlight, {payload: varPendingJson, owner: Lower(User().Email), projectLabel: varPendingProjectLabel, disposition: "pending", exportFileUrl: "", receiptUrl: ""});
        IfError(SaveData(colPendingHighlight, "SponsorHighlightPA31Pending"); true,
            Set(varCanSend, false); Set(varSubmissionStatus, "Browser recovery is unavailable. Nothing was sent. Open the published app in a regular browser window and try again."))
    );
    If(varCanSend,
        Set(varDisposition, "pending");
        IfError(
            With({receipt: PA31TESTONLYSharePointSubmissionEditing.Run(varPendingJson)},
                If(receipt.submissionid = varPendingId && receipt.status = "received",
                    Set(varReceiptUrl, receipt.receipturl);
                    Set(varExportFileUrl, If(receipt.exportstatus = "exported" && receipt.exportfileurl = "https://ornl.sharepoint.com/sites/ResearchEnablement/PA19%20TEST%20ONLY%20JSONL/" & varPendingId & ".jsonl", receipt.exportfileurl, ""));
                    Set(varDisposition, If(!IsBlank(varExportFileUrl), "exported", "received"));
                    Set(varSubmissionStatus, If(varDisposition = "exported", "Highlight received in SharePoint. Its JSONL export is verified and ready for ACORN review. This does not publish a report.", "Highlight received in SharePoint. The JSONL export is not yet confirmed. Select Retry JSONL export to finish safely with the same receipt ID."));
                    ClearCollect(colPendingHighlight, {payload: varPendingJson, owner: Lower(User().Email), projectLabel: varPendingProjectLabel, disposition: varDisposition, exportFileUrl: varExportFileUrl, receiptUrl: varReceiptUrl});
                    IfError(SaveData(colPendingHighlight, "SponsorHighlightPA31Pending"); true, Set(varSubmissionStatus, varSubmissionStatus & " Browser recovery could not store the updated receipt; a retry will safely confirm the same submission.")),
                    receipt.submissionid = varPendingId && receipt.status = "rejected",
                    Set(varDisposition, "rejected"); Set(varSubmissionStatus, "Not submitted. The highlight did not pass validation. Select Edit highlight to correct it, or contact the app owner."),
                    receipt.submissionid = varPendingId && receipt.status = "conflict",
                    Set(varDisposition, "conflict"); Set(varCorrectionConflict, receipt.reason = "stale_revision"); Set(varSubmissionStatus, If(varCorrectionConflict, "A newer correction already exists. Nothing from this edit was saved. Return to the form and choose Load latest submission to review the newer version.", "This receipt ID has different content in SharePoint. Keep this page and contact the app owner with the receipt ID below.")),
                    Set(varDisposition, "pending"); Set(varSubmissionStatus, "We could not confirm the save. Your pending highlight is retained in this browser. Select Retry submission; the same ID prevents a duplicate."))),
            Set(varDisposition, "pending"); Set(varSubmissionStatus, "We could not confirm the save. Your pending highlight is retained in this browser. Select Retry submission; the same ID prevents a duplicate."))
    );
    Set(varSubmitting, false);
    Set(varShowSubmissionResult, true)
)

RestoreDraftButton.OnSelect:
